import{_ as c,C as n,o as d,c as u,j as s,a,E as o,a2 as t}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"Archiver une session","description":"","frontmatter":{"title":"Archiver une session"},"headers":[],"relativePath":"agent/archiver.md","filePath":"agent/archiver.md"}'),m={name:"agent/archiver.md"};function p(h,e,v,g,f,q){const i=n("AskExample"),r=n("Ask"),l=n("Capture");return d(),u("div",null,[e[0]||(e[0]=s("h1",{id:"archiver-une-session",tabindex:"-1"},[a("Archiver une session "),s("a",{class:"header-anchor",href:"#archiver-une-session","aria-label":'Permalink to "Archiver une session"'},"​")],-1)),e[1]||(e[1]=s("p",null,"Ce parcours sert à garder la trace de ce que la session a apporté, pour que la suivante reparte de là. Il a deux modes : une mise à jour du contexte pendant le travail, et une archive complète en fin de session.",-1)),e[2]||(e[2]=s("p",null,[s("strong",null,"L'archivage n'est jamais automatique."),a(" Kessho n'archive rien de lui-même : un archivage a lieu quand l'agent appelle l'outil, parce que vous le lui demandez ou parce qu'il le juge utile et nécessaire. Ce qu'un agent décide de faire seul dépend de ses capacités et des consignes qu'il suit (la procédure livrée avec Kessho, les instructions de votre projet) : certains archivent de leur propre initiative, d'autres attendent votre demande.")],-1)),e[3]||(e[3]=s("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[a("Ce que vous demandez à l'agent "),s("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),e[4]||(e[4]=s("p",null,"Vous pouvez demander à tout moment que le contexte soit mis à jour. Selon ses capacités et ses consignes, l'agent peut aussi le faire de lui-même quand il juge qu'un fait, une décision ou une prochaine étape mérite d'être gardé ; aucune règle de Kessho ne l'y oblige. Pour le provoquer vous-même :",-1)),o(i,{tool:"mem_archive"}),o(r,{say:"Pose ce résumé sur kessho-docs : « Documentation bilingue de Kessho, référence MCP dérivée du catalogue. »",verb:"mem_set_summary",family:"session",args:'{"slug":"kessho-docs","summary":"Documentation bilingue de Kessho, référence MCP dérivée du catalogue."}'}),e[5]||(e[5]=s("p",null,[a("En fin de session, c'est à vous de demander l'archive complète (« on s'arrête », « j'ai fini », ou "),s("code",null,"/mem-archive"),a(" dans Claude Code) ; un agent peut aussi la proposer ou la lancer de lui-même s'il juge la session assez riche :")],-1)),o(r,{say:"On s'arrête là : archive la session de kessho-docs. Elle a posé le plan de la section « Avec un agent » ; retiens aussi le principe « on ne documente que ce que le code soutient ».",verb:"mem_archive",family:"session",args:'{"slug":"kessho-docs","mode":"full","archive_subject":"Plan de la section Avec un agent","archive_body_md":"Plan arrêté : sept parcours, un contrôle des outils cités.","context_md":"## Où en est le projet\\n\\nSection « Avec un agent » en cours de rédaction.\\n\\n## Prochaines étapes\\n\\n1. Relire les sept parcours.","derive":[{"fact":"On ne documente que ce que le code soutient","body":"Une affirmation que le catalogue ne soutient pas n’a pas sa place dans la section.","kind":"principle"}]}'}),o(r,{say:"Annule la dernière archive de kessho-docs, je me suis trompé de projet.",verb:"mem_rollback_archive",family:"session",args:'{"slug":"kessho-docs"}'}),e[6]||(e[6]=t('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="pendant-la-session-le-mode-incremental" tabindex="-1">Pendant la session : le mode incrémental <a class="header-anchor" href="#pendant-la-session-le-mode-incremental" aria-label="Permalink to &quot;Pendant la session : le mode incrémental&quot;">​</a></h3><p><a href="/reference/mcp/session.html#mem-archive"><code>mem_archive</code></a> sans <code>mode</code> (ou avec <code>mode: &quot;incremental&quot;</code>) réécrit <strong>uniquement</strong> le <code>context.md</code> du projet. Aucune archive n&#39;est créée, aucune ligne n&#39;est ajoutée à l&#39;historique.</p><ul><li><code>slug</code> est le seul paramètre obligatoire.</li><li><code>context_md</code> est le <strong>nouveau corps entier</strong> : il remplace l&#39;actuel. Pour le garder tel quel (par exemple pour ne poser qu&#39;une phase), l&#39;agent <strong>omet</strong> le champ. Une chaîne vide est refusée, rien n&#39;est écrit.</li><li><code>phase</code> pose la phase, seulement si elle est fournie. <a href="/reference/mcp/session.html#mem-update-phase"><code>mem_update_phase</code></a> fait la même chose seule, en préservant le corps mot pour mot ; une chaîne vide efface la phase.</li><li><code>expect_decisions</code> liste des décisions qui doivent <strong>survivre</strong> au nouveau corps : si elles n&#39;y sont plus, l&#39;appel est refusé.</li><li>Un lien <code>[[…]]</code> du corps qui ne mène à aucune note est refusé : l&#39;agent corrige ou retire le lien.</li></ul><p>Les refus tombent <strong>avant</strong> la première écriture : un refus ne laisse rien à moitié fait.</p><h3 id="en-fin-de-session-le-mode-complet" tabindex="-1">En fin de session : le mode complet <a class="header-anchor" href="#en-fin-de-session-le-mode-complet" aria-label="Permalink to &quot;En fin de session : le mode complet&quot;">​</a></h3><p><code>mode: &quot;full&quot;</code> fait trois choses : il crée une archive horodatée dans <code>archives/</code> du projet, il ajoute sa ligne en tête de <code>history.md</code>, et il réécrit <code>context.md</code>. Il exige :</p><ul><li><code>archive_subject</code> (le sujet court) et <code>archive_body_md</code> (le corps de l&#39;archive) ;</li><li><strong>ce que la session laisse de durable, ou pourquoi elle n&#39;en laisse pas.</strong> Soit <code>derived_atoms</code> (des liens vers des notes qui existent déjà), soit <code>derive</code>, soit <code>no_derived_because</code> (la raison). Le serveur refuse le <strong>silence</strong> : une archive qui ne dit ni l&#39;un ni l&#39;autre n&#39;est pas écrite. Un simple « rien de durable ce soir » suffit pour <code>no_derived_because</code>, mais pas une chaîne vide. L&#39;idée est qu&#39;un fait resté dans une archive se retrouve plus difficilement qu&#39;une note à part.</li></ul><p><code>derive</code> est le raccourci : une liste de faits (<code>fact</code>, <code>body</code>, <code>kind</code> parmi <code>principle</code>, <code>goal</code>, <code>knowledge</code>) que l&#39;outil écrit lui-même comme notes dans leur zone, avec un lien retour vers la session. Si un des noms est déjà pris, l&#39;archivage <strong>tout entier</strong> est refusé : aucune note n&#39;est écrasée, aucun suffixe n&#39;est ajouté.</p><p>Options : <code>archive_aliases</code> (les mots de tous les jours par lesquels on cherchera cette archive plus tard, ce qui l&#39;aide à ressortir dans <a href="/reference/mcp/rappel.html#mem-search"><code>mem_search</code></a>) et <code>archive_extra_fm</code> (du frontmatter en plus : les listes <code>tags</code> sont fusionnées, les autres clés remplacées).</p><p>Les liens <code>[[…]]</code> sont contrôlés comme en mode incrémental, dans les deux corps (ceux des notes que <code>derive</code> va créer comptent comme existants). Le projet doit être actif : un projet archivé est refusé (voir <a href="/agent/reprendre.html">Reprendre un projet</a>).</p><h3 id="apres-l-archive" tabindex="-1">Après l&#39;archive <a class="header-anchor" href="#apres-l-archive" aria-label="Permalink to &quot;Après l&#39;archive&quot;">​</a></h3><ul><li><a href="/reference/mcp/session.html#mem-set-summary"><code>mem_set_summary</code></a> pose le résumé court du projet, 300 caractères au plus, dans le frontmatter de <code>context.md</code>. Le catalogue demande de l&#39;appeler après chaque archivage : le résumé est écrit par l&#39;agent, le vault ne peut pas le deviner.</li><li>Si la mémoire est un dépôt git et que la case <strong>Automatisme</strong> (« Les agents commitent et synchronisent automatiquement », dans <strong>Réglages › Synchronisation</strong>) est cochée, l&#39;automatisme de Kessho commite et pousse ce que l&#39;outil vient d&#39;écrire, et la procédure demande à l&#39;agent d&#39;appeler <a href="/reference/mcp/git.html#mem-git-sync"><code>mem_git_sync</code></a> en fin de session. Voir <a href="/agent/synchroniser.html">Synchroniser la mémoire</a>.</li></ul><h3 id="annuler-la-derniere-archive" tabindex="-1">Annuler la dernière archive <a class="header-anchor" href="#annuler-la-derniere-archive" aria-label="Permalink to &quot;Annuler la dernière archive&quot;">​</a></h3><p><a href="/reference/mcp/session.html#mem-rollback-archive"><code>mem_rollback_archive</code></a> (<code>slug</code>) <strong>supprime</strong> la dernière archive du projet et retire sa ligne de <code>history.md</code>. Deux limites, dites par le catalogue et par le code :</p><ul><li><code>context.md</code> <strong>n&#39;est pas restauré</strong> : il garde le corps que l&#39;archive avait écrit.</li><li>les notes écrites par <code>derive</code> ne sont pas retirées : l&#39;outil ne touche que l&#39;archive et l&#39;historique.</li></ul><p><strong>L&#39;outil n&#39;a aucune garde</strong> : pas de <code>confirm</code>, il supprime dès l&#39;appel. Il vaut mieux que l&#39;agent vous demande confirmation avant de l&#39;appeler.</p><p>L&#39;archive supprimée ne va pas dans une corbeille : seul l&#39;historique git, si elle y avait été commitée, la garde.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2>',19)),o(l,{name:"fraicheur",alt:"Le témoin de fraîcheur, en haut à droite : un agent vient d'écrire, le témoin s'allume et dit quelle zone a bougé."}),e[7]||(e[7]=t('<p>Quand l&#39;agent écrit, le <strong>témoin de fraîcheur</strong> (la pastille en haut à droite) s&#39;allume. Son panneau dit depuis quand et quelle zone a bougé ; <strong>Relire</strong> recharge l&#39;écran (voir <a href="/guide/zones.html">Zones</a>).</p><p>Une archive apparaît dans la zone <strong>Sessions</strong>, sous son projet ; le contexte est celui que lit l&#39;écran <strong>Clés de contexte</strong>, avec le nombre d&#39;archives et la date de la dernière session (voir <a href="/guide/home.html">Accueil</a>). Le champ <strong>GIT</strong> de la barre d&#39;état dit où en sont les commits (voir <a href="/guide/sync.html">Synchronisation</a>).</p>',2))])}const x=c(m,[["render",p]]);export{b as __pageData,x as default};
